import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0004: 为什么采用 Resource + Dependency Graph","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0004-why-resource-dependency-graph.md","filePath":"zh/adr/ADR-0004-why-resource-dependency-graph.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0004-why-resource-dependency-graph.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0004-为什么采用-resource-dependency-graph" tabindex="-1">ADR-0004: 为什么采用 Resource + Dependency Graph <a class="header-anchor" href="#adr-0004-为什么采用-resource-dependency-graph" aria-label="Permalink to “ADR-0004: 为什么采用 Resource + Dependency Graph”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/resources.md §3，ADR-0005</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>真实故障的正确处理由拓扑决定：数据库挂了，应用的重启毫无意义；代理断了， Tunnel 的&quot;恢复&quot;只会空转。资源不是平铺的监控项，而是一张有向依赖图。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p><code>Resource</code> 描述对象（探针、健康策略、恢复策略），<code>Dependency</code> 描述前置条件 （required/optional/conditional + <code>HealthCondition</code>），配置加载期把二者构建为 <code>DependencyGraph</code>：悬空引用、重复 ID、不可能条件、环都在启动期报出具体字段路径， 拒绝启动而不是运行期死锁。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>平铺资源列表</strong>：恢复无顺序语义，&quot;先修 db 再修 app&quot;无法表达。</li><li><strong>隐式探测顺序（按配置顺序）</strong>：顺序是巧合不是语义，改配置顺序即改行为。</li><li><strong>运行期动态发现依赖</strong>：无验证时机，错误发现得越晚代价越大。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：恢复顺序可推导（拓扑序）；启动期把所有结构性错误一次性拒绝； 条件依赖（<code>conditional_on</code>）与备选组（<code>alternative_groups</code>）表达冗余与降级语义。 缺点：建模学习成本；配置错误在启动期暴露（这是特性不是缺陷）。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>graph.rs 的环检测返回具体环路径（ADR-0014）。</li><li>引擎的 waiter 去重（§3.6）建立在图语义上：同一依赖的所有等待者共享一次恢复结果。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};